contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function performing the property test
    // We take an input sendAmount but only send it if nonzero via low-level call because C.sudicideAnyone is non-payable.
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure we have funds if we intend to forward any (though we won't call the non-payable with value)
        require(address(this).balance >= sendAmount);

        uint balBeforeC = address(c).balance;
        uint balBeforeThis = address(this).balance;

        // Call sudicideAnyone without sending Ether (function is non-payable). Capture whether it reverted.
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfterC = address(c).balance;
        uint balAfterThis = address(this).balance;

        // General rule: if the call did not revert then C's balance is zero afterwards
        // and this contract's balance did not decrease.
        assert(reverted || (balAfterC == 0 && balAfterThis >= balBeforeThis));
    }

    receive() external payable {}
}

